/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { provideRouter, Router } from '@angular/router';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { ErrorModalComponent } from './error-modal.component';

describe('ErrorModalComponent', () => {
  it('closes dialog and marks notify', () => {
    const dialogRef = { close: jasmine.createSpy('close') } as unknown as MatDialogRef<ErrorModalComponent>;
    const data = { notify: false };
    const router = { navigate: jasmine.createSpy('navigate') } as unknown as Router;

    TestBed.configureTestingModule({
      imports: [ErrorModalComponent, TranslocoTestingModule.forRoot({ langs: {} })],
      providers: [
        { provide: MatDialogRef, useValue: dialogRef },
        { provide: MAT_DIALOG_DATA, useValue: data },
        { provide: Router, useValue: router },
      ],
    });

    const fixture = TestBed.createComponent(ErrorModalComponent);
    const component = fixture.componentInstance;

    component.close();

    expect(data.notify).toBeTrue();
    expect(dialogRef.close).toHaveBeenCalledWith(data);
  });

  it('redirects and closes', () => {
    const dialogRef = { close: jasmine.createSpy('close') } as unknown as MatDialogRef<ErrorModalComponent>;
    const data = {};
    const router = { navigate: jasmine.createSpy('navigate') } as unknown as Router;

    TestBed.configureTestingModule({
      imports: [ErrorModalComponent, TranslocoTestingModule.forRoot({ langs: {} })],
      providers: [
        { provide: MatDialogRef, useValue: dialogRef },
        { provide: MAT_DIALOG_DATA, useValue: data },
        { provide: Router, useValue: router },
      ],
    });

    const fixture = TestBed.createComponent(ErrorModalComponent);
    const component = fixture.componentInstance;

    component.redirect('/home');

    expect(dialogRef.close).toHaveBeenCalled();
    expect(router.navigate).toHaveBeenCalledWith(['/home']);
  });

  describe('sign in', () => {
    function setup(data: any) {
      const dialogRef = { close: jasmine.createSpy('close') } as unknown as MatDialogRef<ErrorModalComponent>;
      TestBed.configureTestingModule({
        imports: [ErrorModalComponent, TranslocoTestingModule.forRoot({ langs: {} })],
        providers: [
          provideRouter([]),
          { provide: MatDialogRef, useValue: dialogRef },
          { provide: MAT_DIALOG_DATA, useValue: data },
        ],
      });
      const fixture = TestBed.createComponent(ErrorModalComponent);
      fixture.detectChanges();
      return { fixture, dialogRef };
    }

    it('shows the sign-in button when the error offers it, and closes before signing in', () => {
      const login = jasmine.createSpy('login');
      const { fixture, dialogRef } = setup({ error: { status: 401 }, login });

      const button: HTMLButtonElement = fixture.nativeElement.querySelector('.actions button');
      expect(button.textContent).toContain('auth.unauthorized.login');
      button.click();

      expect(dialogRef.close).toHaveBeenCalled();
      expect(login).toHaveBeenCalled();
    });

    it('hides the sign-in button otherwise', () => {
      const { fixture } = setup({ error: { status: 401 } });
      expect(fixture.nativeElement.querySelector('.actions button')).toBeNull();
    });
  });
});
